// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md / microarchitecture.md (rr_arbiter).
// State: one priority pointer `ptr`, $clog2(N) bits, reset to 0.
// grant is combinational from req and ptr; ptr moves to one past the
// winner on every rising edge with a grant, and holds otherwise.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);
    localparam integer PW  = (N > 1) ? $clog2(N) : 1;
    localparam [N-1:0] ONE = {{(N-1){1'b0}}, 1'b1};

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_nxt;
    reg  [PW-1:0] sel;
    reg           found;
    integer       k;
    integer       idx;
    integer       winner;
    integer       nxt;

    // Wrapping priority search from ptr; every output defaulted first.
    always @* begin
        grant  = {N{1'b0}};
        found  = 1'b0;
        winner = 0;
        idx    = 0;
        sel    = {PW{1'b0}};
        for (k = 0; k < N; k = k + 1) begin
            idx = k + {{(32-PW){1'b0}}, ptr};
            if (idx >= N) begin
                idx = idx - N;
            end
            sel = idx[PW-1:0];
            if (!found && req[sel]) begin
                found  = 1'b1;
                winner = idx;
                grant  = ONE << sel;
            end
        end
    end

    // Next pointer: one past the winner, wrapping at N (not at 2**PW).
    always @* begin
        nxt = winner + 1;
        if (nxt >= N) begin
            nxt = 0;
        end
        ptr_nxt = found ? nxt[PW-1:0] : ptr;
    end

    // Pointer register: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_nxt;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    wire [31:0] f_wdist;
    assign f_wdist = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr < N);
            assert ((grant & (grant - ONE)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            if (found) assert (grant == (ONE << winner));
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) assert (ptr == 0);
            if ($past(rst_n) && $past(found))
                assert (ptr == (($past(winner) + 1) % N));
            if ($past(rst_n) && !$past(found))
                assert (ptr == $past(ptr));
            cover (rst_n && (&req));
            cover ($past(rst_n) && ($past(ptr) == N - 1) && (ptr == 0));
        end
    end

    genvar gi;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_fair
            reg  [31:0] f_wait;
            wire [31:0] f_dist;
            assign f_dist = (gi >= ptr) ? (gi - ptr) : (gi + N - ptr);
            always @(posedge clk) begin
                if (!rst_n)
                    f_wait <= 32'd0;
                else if (req[gi] && !grant[gi])
                    f_wait <= f_wait + 32'd1;
                else
                    f_wait <= 32'd0;
            end
            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                    if (req[gi] && (grant != {N{1'b0}}))
                        assert (f_dist >= f_wdist);
                end
            end
            always @(*) cover (f_past_valid && rst_n && grant[gi]);
        end
    endgenerate
`endif
endmodule
