// Self-checking checker: reference pointer model, fairness, coverage.
module rr_arbiter_chk #(
    parameter integer N = 4
) (
    input wire         clk,
    input wire         rst_n,
    input wire [N-1:0] req,
    input wire [N-1:0] grant,
    input wire         final_chk
);
    localparam integer PW  = $clog2(N);
    localparam [N-1:0] ONE = {{(N-1){1'b0}}, 1'b1};

    integer passed;
    integer failed;
    integer m_ptr;
    integer k;
    integer i;
    integer idx;
    integer win;
    reg     found;
    reg     m_valid;
    reg     cov_done;
    reg [PW-1:0] ii;
    reg [N-1:0]  exp_g;
    reg [N-1:0]  prev_req;
    integer wait_cnt  [0:N-1];
    integer cov_alone [0:N-1];
    integer cov_none;
    integer cov_all;
    integer cov_held;
    integer cov_maxwait;
    integer cov_rst;
    integer cov_wrap;

    initial begin
        passed = 0; failed = 0; m_ptr = 0;
        found = 1'b0; m_valid = 1'b0; cov_done = 1'b0;
        exp_g = {N{1'b0}}; prev_req = {N{1'b0}};
        win = 0; idx = 0; ii = {PW{1'b0}};
        cov_none = 0; cov_all = 0; cov_held = 0;
        cov_maxwait = 0; cov_rst = 0; cov_wrap = 0;
        for (i = 0; i < N; i = i + 1) begin
            ii = i[PW-1:0];
            wait_cnt[ii]  = 0;
            cov_alone[ii] = 0;
        end
    end

    always @(posedge clk) begin
        if (m_valid) begin
            // Reference model: first requester at or after the pointer.
            exp_g = {N{1'b0}};
            found = 1'b0;
            win   = 0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (m_ptr + k) % N;
                ii  = idx[PW-1:0];
                if (!found && req[ii]) begin
                    found = 1'b1;
                    win   = idx;
                    exp_g = ONE << ii;
                end
            end
            if (grant !== exp_g) begin
                failed = failed + 1;
                $error("rr_arbiter N=%0d at %0t: req=%b grant=%b, expected %b (model pointer %0d)",
                       N, $time, req, grant, exp_g, m_ptr);
            end else begin
                passed = passed + 1;
            end

            // Fairness: a held request waits at most N-1 cycles.
            for (i = 0; i < N; i = i + 1) begin
                ii = i[PW-1:0];
                if (!rst_n) begin
                    wait_cnt[ii] = 0;
                end else if (req[ii] && !grant[ii]) begin
                    wait_cnt[ii] = wait_cnt[ii] + 1;
                    if (wait_cnt[ii] > N - 1) begin
                        failed = failed + 1;
                        $error("rr_arbiter N=%0d at %0t: requester %0d has waited %0d cycles (bound %0d)",
                               N, $time, i, wait_cnt[ii], N - 1);
                    end else begin
                        passed = passed + 1;
                    end
                end else begin
                    if (req[ii] && grant[ii] && (wait_cnt[ii] == N - 1))
                        cov_maxwait = cov_maxwait + 1;
                    wait_cnt[ii] = 0;
                end
            end

            // Coverage.
            if (rst_n) begin
                if (req == {N{1'b0}}) cov_none = cov_none + 1;
                if (&req) cov_all = cov_all + 1;
                if (((req & prev_req) != {N{1'b0}}) && ((req ^ prev_req) != {N{1'b0}}))
                    cov_held = cov_held + 1;
                for (i = 0; i < N; i = i + 1) begin
                    ii = i[PW-1:0];
                    if (req == (ONE << ii)) cov_alone[ii] = cov_alone[ii] + 1;
                end
                if (found && (win == N - 1)) cov_wrap = cov_wrap + 1;
            end else if (req != {N{1'b0}}) begin
                cov_rst = cov_rst + 1;
            end

            // Model pointer update.
            if (!rst_n) m_ptr = 0;
            else if (found) m_ptr = (win + 1) % N;
        end

        if (!rst_n) begin
            m_valid = 1'b1;
            m_ptr   = 0;
            for (i = 0; i < N; i = i + 1) begin
                ii = i[PW-1:0];
                wait_cnt[ii] = 0;
            end
        end
        prev_req = req;

        if (final_chk && !cov_done) begin
            cov_done = 1'b1;
            if (cov_none > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("rr_arbiter N=%0d: coverage goal not reached: no requests", N); end
            if (cov_all > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("rr_arbiter N=%0d: coverage goal not reached: everyone requesting", N); end
            if (cov_held > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("rr_arbiter N=%0d: coverage goal not reached: held request among changing others", N); end
            if (cov_maxwait > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("rr_arbiter N=%0d: coverage goal not reached: longest fair wait N-1", N); end
            if (cov_rst > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("rr_arbiter N=%0d: coverage goal not reached: reset during traffic", N); end
            if (cov_wrap > 0) passed = passed + 1;
            else begin failed = failed + 1; $error("rr_arbiter N=%0d: coverage goal not reached: pointer wrap N-1 to 0", N); end
            for (i = 0; i < N; i = i + 1) begin
                ii = i[PW-1:0];
                if (cov_alone[ii] > 0) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("rr_arbiter N=%0d: coverage goal not reached: requester %0d alone", N, i);
                end
            end
        end
    end
endmodule

// Top-level testbench: N=4 and N=5 arbiters side by side.
module rr_arbiter_tb;
    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;
    reg        final_chk;
    integer    passed;
    integer    failed;
    integer    total_pass;
    integer    total_fail;
    integer    c;
    integer    i;
    integer    rnd;
    integer    rnd2;
    reg [8*64-1:0] nonce;

    rr_arbiter #(.N(4)) dut4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) dut5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    rr_arbiter_chk #(.N(4)) chk4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4), .final_chk(final_chk));
    rr_arbiter_chk #(.N(5)) chk5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5), .final_chk(final_chk));

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task check4;
        input [3:0] got;
        input [3:0] want;
        begin
            if (got !== want) begin
                failed = failed + 1;
                $error("N=4 directed check at %0t: grant=%b, expected %b", $time, got, want);
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    task check5;
        input [4:0] got;
        input [4:0] want;
        begin
            if (got !== want) begin
                failed = failed + 1;
                $error("N=5 directed check at %0t: grant=%b, expected %b", $time, got, want);
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    initial begin
        passed = 0; failed = 0; final_chk = 1'b0;
        rst_n = 1'b0; req4 = 4'b0000; req5 = 5'b00000;
        rnd = 0; rnd2 = 0;
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};

        // Reset.
        repeat (3) @(negedge clk);
        rst_n = 1'b1;

        // No requests.
        repeat (4) @(negedge clk);
        #1;
        check4(grant4, 4'b0000);
        check5(grant5, 5'b00000);

        // Each requester alone.
        for (i = 0; i < 5; i = i + 1) begin
            @(negedge clk);
            req4 = (i < 4) ? (4'b0001 << i) : 4'b0000;
            req5 = 5'b00001 << i;
            repeat (3) begin
                #1;
                check4(grant4, req4);
                check5(grant5, req5);
                @(negedge clk);
            end
        end

        // Reset, then everyone requesting: strict rotation from 0.
        req4 = 4'b0000; req5 = 5'b00000; rst_n = 1'b0;
        @(negedge clk);
        rst_n = 1'b1; req4 = 4'b1111; req5 = 5'b11111;
        for (c = 0; c < 20; c = c + 1) begin
            #1;
            check4(grant4, 4'b0001 << (c % 4));
            check5(grant5, 5'b00001 << (c % 5));
            @(negedge clk);
        end

        // A held request among changing others.
        for (c = 0; c < 60; c = c + 1) begin
            rnd = $random;
            req4 = rnd[3:0] | 4'b0100;
            req5 = rnd[8:4] | 5'b01000;
            @(negedge clk);
        end

        // Random subsets, dense and sparse, with drops and re-raises.
        for (c = 0; c < 600; c = c + 1) begin
            rnd = $random;
            if ((c % 3) == 0) begin
                rnd2 = $random;
                rnd = rnd & rnd2;
            end
            req4 = rnd[3:0];
            req5 = rnd[8:4];
            @(negedge clk);
        end

        // Reset during traffic.
        for (c = 0; c < 40; c = c + 1) begin
            rnd = $random;
            req4 = rnd[3:0] | 4'b1000;
            req5 = rnd[8:4] | 5'b10000;
            rst_n = ((c == 15) || (c == 16) || (c == 30)) ? 1'b0 : 1'b1;
            @(negedge clk);
        end
        rst_n = 1'b1;

        // More random traffic after reset.
        for (c = 0; c < 200; c = c + 1) begin
            rnd = $random;
            req4 = rnd[3:0];
            req5 = rnd[8:4];
            @(negedge clk);
        end

        // Drain and final coverage check.
        req4 = 4'b0000; req5 = 5'b00000;
        repeat (4) @(negedge clk);
        final_chk = 1'b1;
        repeat (2) @(negedge clk);

        total_pass = passed + chk4.passed + chk5.passed;
        total_fail = failed + chk4.failed + chk5.failed;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_pass, total_fail);
        $finish;
    end
endmodule
=== END FILE ===
